MATCH p = (start:PlantItem {tag: 'BV-1-9'})-[:send_to*]->(end:PlantItem {tag: 'TK-49-4'})
RETURN [n IN nodes(p) | n.tag] AS path_tags, length(p) AS hops
ORDER BY hops;

MATCH (t:Tank:PlantItem {tag:'TK-29-1'})
MATCH (v:PlantItem)-[:send_to*1..]->(t)
WHERE (v:BallValve OR v:GlobeValve OR v:OperatedValve)
  AND NOT (v:CheckValve)
  AND NOT EXISTS {
    MATCH (:ProcessInstrumentationFunction)-[:send_signal_to]->(:ActuatingFunction)-[:control]->(v)
  }
RETURN DISTINCT v.tag AS valve_to_close;
